let alert;
try {
    alert = (typeof msg.payload === "string")
        ? JSON.parse(msg.payload)
        : msg.payload;
} catch (e) {
    alert = { raw: msg.payload };
}

const symbol = (alert.symbol || "unknown").toLowerCase();
const ts = Date.now();
const rnd = Math.floor(Math.random() * 1e6);

const tsnew = (alert.timestamp_utc || new Date().toISOString()).replace(/[:.]/g, "-");

const jsonText = JSON.stringify(alert);
const buf = Buffer.from(jsonText, "utf8");

msg.bucket = "alertsnode";
//msg.object = `alerts/${symbol}/${tsnew}_${Math.floor(Math.random() * 1e6)}.json`; 
msg.object = `alerts/${symbol}/${tsnew}.json`;
msg.objectName = msg.object;
msg.stream = buf;
msg.size = buf.length;
msg.metaData = {
    "Content-Type": "application/json"
};

// --- (Flattening metrics) ---
const coin = symbol.toUpperCase();
const priceKey = `${coin}_price`;

msg.payload = {
    symbol: coin,
    [priceKey]: alert.metrics ? alert.metrics.price : null,
    event_type: alert.event_type,
    message: alert.message,
    timestamp_utc: alert.timestamp_utc
};

return msg;
